22	    issueDate: '2026-10-07',
23	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
24	  });
25	
26	  const issueResult = issueInvoice(result.value, []);
27	  const text = renderInvoiceText(issueResult.value);
28	  const lines = text.split('\n');
